<template><section><PageHeading eyebrow="YOUR CONVERSATION ARCHIVE" title="每一段对话，都值得留存。" description="在这里，重新发现聊天记录里的日常与灵感。"><button class="btn" :disabled="workspace.loading||loading" @click="refreshAll"><UiIcon name="refresh" :size="15"/>刷新数据</button></PageHeading><div class="hero"><div class="hero-copy"><div class="eyebrow">A LITTLE SPACE FOR YOUR MEMORIES</div><h2>把散落的对话，整理成自己的档案。</h2><p>查找一句话，重温一个瞬间，发现沟通里的点滴。</p><button class="btn btn-primary" @click="go('/chatlog')">打开聊天记录<UiIcon name="arrow" :size="14"/></button></div><img class="hero-art" :src="assetUrl('archive.svg')" alt="纸张、对话气泡与档案夹的原创插画"/></div><div class="stats-grid"><button v-for="item in metrics" :key="item.label" class="stat stat-action" style="text-align:left" @click="go(item.path)"><div class="stat-top"><span>{{ item.label }}</span><span class="stat-icon"><UiIcon :name="item.icon" :size="16"/></span></div><div class="stat-value">{{ item.value }}<small>{{ item.unit }}</small></div><div class="stat-bottom">{{ item.note }}</div></button></div><div class="dashboard-chart-row"><article class="panel"><div class="panel-head"><div><h3>消息趋势</h3><p class="panel-subtitle">对话在时间里留下的痕迹</p></div><div class="segment-control" aria-label="趋势时间范围"><button v-for="d in [7,30,90]" :key="d" :class="{active:days===d}" :aria-pressed="days===d" @click="days=d">{{ d }} 天</button></div></div><div class="panel-body"><StatePanel v-if="loading" kind="loading"/><StatePanel v-else-if="error" kind="error" title="消息暂时无法读取" :description="error" @retry="refresh(true)"/><template v-else><div class="chart-summary"><strong>{{ number(stats.total) }}</strong><span>条已读取消息 · {{ days }} 天</span></div><TrendChart :points="stats.daily"/></template></div></article><article class="panel"><div class="panel-head"><div><h3>消息类型</h3><p class="panel-subtitle">有文字，也有声音与画面</p></div><UiIcon name="chart" :size="17"/></div><div class="panel-body"><StatePanel v-if="loading" kind="loading"/><StatePanel v-else-if="error" title="等待数据" description="重新连接后查看分布"/><TypeDonut v-else :items="stats.types"/></div><div class="panel-foot"><UiIcon name="info" :size="12"/>与左侧使用相同时间范围和数据来源</div></article></div><SampleNotice :sample="sample"/><div class="dashboard-bottom-row content-gap"><article class="panel"><div class="panel-head"><div class="panel-title"><h3>最近会话</h3><span class="count">{{ workspace.sessions.length }}</span></div><button class="text-button" @click="go('/sessions')">查看全部<UiIcon name="arrow" :size="13"/></button></div><div class="panel-body"><StatePanel v-if="workspace.loading" kind="loading"/><StatePanel v-else-if="workspace.errors.sessions" kind="error" title="会话读取失败" :description="workspace.errors.sessions" @retry="refreshAll"/><StatePanel v-else-if="!workspace.sessions.length" title="还没有会话" description="连接服务或导入本地数据库后，对话会显示在这里。"/><template v-else><button v-for="session in workspace.sessions.slice(0,4)" :key="session.id" class="activity-row" @click="openChat(session)"><UiAvatar :name="session.name" :group="session.kind==='room'"/><div class="activity-info"><strong>{{ session.name }}</strong><p class="truncate">{{ session.preview||'打开查看这段对话' }}</p></div><span class="activity-time">{{ formatTime(session.lastMessageTime,true) }}</span><UiIcon name="chevron" :size="14"/></button></template></div></article><article class="panel"><div class="panel-head"><h3>继续探索</h3><UiIcon name="bolt" :size="16"/></div><div class="panel-body"><button v-for="action in actions" :key="action.path" class="quick-link" @click="go(action.path)"><span class="quick-icon"><UiIcon :name="action.icon" :size="19"/></span><div><strong>{{ action.title }}</strong><p>{{ action.description }}</p></div><UiIcon name="arrow" :size="15"/></button></div></article></div></section></template>
<script>
import { computed } from 'vue'
import { useRouter } from 'vue-router'
import { workspace,loadWorkspace } from '@/lib/workspace'
import useSample from '@/lib/useSample'
import { number,formatTime,toDate } from '@/lib/data'
import { clock,assetUrl } from '@/lib/demo'
import UiIcon from '@/components/ui/UiIcon.vue'
import UiAvatar from '@/components/ui/UiAvatar.vue'
import PageHeading from '@/components/ui/PageHeading.vue'
import StatePanel from '@/components/ui/StatePanel.vue'
import SampleNotice from '@/components/ui/SampleNotice.vue'
import TrendChart from '@/components/charts/TrendChart.vue'
import TypeDonut from '@/components/charts/TypeDonut.vue'
export default {name:'ArchiveDashboard',components:{UiIcon,UiAvatar,PageHeading,StatePanel,SampleNotice,TrendChart,TypeDonut},setup(){const router=useRouter(),sample=useSample(30);const referenceDate=()=>sample.sample.value?.local?new Date(sample.sample.value.end):clock();const metric=(key)=>!workspace.ready||workspace.errors[key]?'—':number(workspace[key].length);const metrics=computed(()=>[{label:'联系人',icon:'user',value:metric('contacts'),unit:'位',note:'档案里的每一个熟悉名字',path:'/contacts'},{label:'群聊',icon:'users',value:metric('chatrooms'),unit:'个',note:'一起讨论，一起分享',path:'/chatrooms'},{label:'会话',icon:'inbox',value:metric('sessions'),unit:'段',note:'已载入的会话列表',path:'/sessions'},{label:sample.sample.value?.local?'档案末 7 天活跃会话':'近 7 天活跃会话',icon:'chat',value:!workspace.ready||workspace.errors.sessions?'—':number(workspace.sessions.filter(s=>{const d=toDate(s.lastMessageTime);return d&&d<=referenceDate()&&d>=new Date(referenceDate().getTime()-7*86400000)}).length),unit:'段',note:'基于会话最后消息时间',path:'/sessions'}]);const actions=[{icon:'search',title:'找回一段对话',description:'从关键词、日期或联系人开始',path:'/chatlog'},{icon:'chart',title:'发现聊天习惯',description:'看看沟通的节奏与高频话题',path:'/analytics'},{icon:'image',title:'翻阅媒体档案',description:'把图片、文件和声音重新找回来',path:'/media'}];const refreshAll=async()=>{await loadWorkspace(true);sample.refresh(true)};return {...sample,workspace,metrics,actions,number,formatTime,assetUrl,refreshAll,go:path=>router.push(path),openChat:s=>router.push({path:'/chatlog',query:{talker:s.id}})}}}
</script>
